// The program the Motif view starts from when it has nothing else to show:
// short enough to read in one go, and touching each part of the language — a
// song, instruments, lanes, sections, chords that move as little as they can,
// a seeded random walk, a transformation (the walk played backwards) and
// chance in the drums. test/node/motif-music.test.js builds it.

export const MOTIF_EXAMPLE = `tml 1
// An example to start from: eight bars in 19-tone equal temperament, half
// written down and half generated by rules. Change the seed and build again
// (Ctrl+Enter) for another tune. Docs → Motif Language has the whole language.

song {
  title: "Motif example"
  tuning: "19-TET"
  tempo: 96
  speed: 6
  bars: 8
  bar_rows: 16
  beat_rows: 4
  global_volume: 255
  mixing_volume: 160
  seed: 19            // the same seed always builds the same song
}

instrument PIANO { bank: 0, program: 0 }
instrument PAD   { bank: 0, program: 89 }
instrument BASS  { bank: 0, program: 33 }
instrument KIT   { bank: 128, program: 0 }

lane tune { inst: PIANO, pan: $90 }
lane pad1 { inst: PAD, pan: $60 }
lane pad2 { inst: PAD, pan: $80 }
lane pad3 { inst: PAD, pan: $A0 }
lane bass { inst: BASS }
lane kick { inst: KIT }
lane hat  { inst: KIT, pan: $A8, jitter: 4 }

section "walk" 1..4
section "back" 5..8

// ── harmony: a chord a bar. In 19-TET a major third is 6 steps, a minor
// third 5 and a fifth 11.
fn triad(root, third) { return { root: degree(root), ivs: [0, third, 11] } }
let CHORDS = [triad("C", 6), triad("A", 5), triad("F", 6), triad("G", 6)]
let PADS = [pad1, pad2, pad3]
let held = notes("C4 E4 G4")
for bar in 1..8 {
  let chord = CHORDS[(bar - 1) % 4]
  held = nearest_chord(held, chord, 'G3', 'G4')   // move each note as little as it can
  for i, p in held { hit(PADS[i], at(bar), p, 26) }
  let root = period() * 2 + chord.root            // the root, two periods up from C0
  hit(bass, at(bar), root, 50)
  hit(bass, at(bar, 8), root + 11, 40)
}

// ── the tune: a random walk up and down the major scale, a quarter note a
// step, and then the same walk backwards so the second half answers the first.
let SCALE = notes("C5 D5 E5 F5 G5 A5 B5 C6")
let walk = []
let i = 4
for _ in 1..16 {
  i = clamp(i + choose([-2, -1, -1, 1, 1, 2]), 0, len(SCALE) - 1)
  push(walk, SCALE[i])
}
for n, p in walk + reverse(walk) {
  hit(tune, n * 4, p, if n % 4 == 0 then 48 else 38)
}

// ── drums: the kick on the beat and now and then one more; hats by a loose hand
for bar in 1..8 {
  hit(kick, at(bar), midi(36), 50)
  hit(kick, at(bar, 8), midi(36), 46)
  if chance(0.4) { hit(kick, at(bar, 14), midi(36), 34) }
  for r in 0..<16 by 2 { hit(hat, at(bar, r), midi(42), random_int(18, 30) + (if r % 4 == 0 then 6 else 0)) }
}
`;
